# 标准化
features_norm = (features - knn_mean) / knn_std

# 计算每个样本到所有中心的距离，找第K近的距离
distances = []
for sample in features_norm:
    # 计算到每个中心的欧氏距离
    dists = np.sqrt(np.sum((knn_train_data - sample) ** 2, axis=1))
    # 排序取第K近（K=5，索引4）
    dists.sort()
    distances.append(dists[K-1])

distances = np.array(distances)
correct = np.mean(distances <= threshold)
print(f"训练集样本数：{len(features)}")
print(f"阈值：{threshold:.6f}")
print(f"匹配通过率（距离<=阈值）：{correct*100:.1f}%")
